note("c a f e").withHap(x=>{
  if (x.value.note == 'c') {
    x.value.s = 'gm_piano'
  }
  else {
    x.value.s = 'gm_piano'
    x.value.n = 2
  }
  return x
})

note("[a b, c d] a b c d").s("gm_piano").withHaps(x=>{
  if (x.length > 1) {
    x = x.map(hap => hap.withValue(val => {
      return {
        n: 1,
        // select gm_piano:1 sample
        ...val
      }
    }));
  }
  return x
})
